window.AUTH=window.AUTH||{};window.AUTH["23-108"]={"d":"23-108","id":"2023/23-108","n":"Snyder v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner James E. Snyder","date":"2024-02-05","url":"https://www.supremecourt.gov/DocketPDF/23/23-108/299751/20240205125508613_Snyder%20Brief%20for%20Petitioner.pdf","side":"pet","n":71},{"k":"respondent","label":"Brief of respondent United States","date":"2024-03-11","url":"https://www.supremecourt.gov/DocketPDF/23/23-108/302853/20240311193806471_23-108bsUnitedStates.pdf","side":"res","n":82},{"k":"reply","label":"Reply of petitioner James E. Snyder","date":"2024-04-02","url":"https://www.supremecourt.gov/DocketPDF/23/23-108/306485/20240402120917827_Snyder%20Reply%20Brief.pdf","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r48_g3ci.pdf","tr":true,"items":[{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"op":2,"ar":9,"sum":"The Court held that the jury instructions failed to convey that the federal document law required a \"consciousness of wrongdoing\" for conviction. There was nothing inherently corrupt in ordering employees to destroy documents, even if the aim was to keep the documents from the government.","sumSrc":"Oyez","by":{"0":"25","1":"39","2":"8"}},{"t":"case","label":"Atl. Richfield Co. v. Christian","cite":"140 S. Ct. 1335","y":2020,"id":"2019/17-1498","sc":1,"sum":"The Court held that the landowners in this case were potentially responsible parties under the Comprehensive Environmental Response, Compensation, and Liability Act (CERCLA) and thus need the Environmental Protection Agency’s approval to take remedial action.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"sum":"Pursuant to §523(a)(2)(A) of the Bankruptcy Code, a debtor like Kate Bartenwerfer who is liable for her partner’s fraud cannot discharge that debt in bankruptcy, regardless of her own culpability.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"sum":"The Court upheld the sentencing hike, stating that the definition of a felony drug offense in 12 U.S.C. 841 as punishable by imprisonment for more than one year was controlling regardless of whether South Carolina classified the offense as a felony or a misdemeanor.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Ciminelli v. United States","cite":"598 U.S. 306","y":2023,"id":"2022/21-1170","sc":1,"op":1,"sum":"The Second Circuit’s right-to-control theory—under which the Government can establish federal wire fraud by showing that the defendant schemed to deprive a victim of potentially valuable economic information necessary to make discretionary economic decisions—cannot form the basis for a conviction under the federal fraud statutes because the right to control is not grounded in a traditional property interest.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25","2":"23"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"0":"48","2":"21"}},{"t":"case","label":"Commonwealth v. Lapham","cite":"31 N.E. 638","y":1892,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./31/638/","by":{"0":"24"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"sum":"Section 209(a) does not apply to a severance payment that is made to encourage the payee to accept Government employment, but is made before the payee becomes a Government employee.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","1":"7"}},{"t":"case","label":"Dickinson v. Van De Carr","cite":"87 A.D. 386","y":1903,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D./87/386/","by":{"0":"18"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"op":1,"sum":"Under 18 U. S. C. §1028A(a)(1)’s crime of “aggravated identity theft,” a defendant “uses” another person’s means of identification “in relation to” a predicate offense when the use is at the crux of what makes the conduct criminal.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26, 36, 40","2":"10, 15"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"op":2,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"28, 35"}},{"t":"case","label":"Fischer v. United States","cite":"529 U.S. 667","y":2000,"id":"1999/99-116","sc":1,"op":2,"ar":1,"sum":"The Court held that \"Health care providers such as the one defrauded by [Fischer] receive 'benefits' within the meaning of [the federal bribery statute].\" Thus, the Medicare funds hospitals receive for treating Medicare patients subject people who bribe hospital officials to federal prosecution. \"The government has a legitimate and significant interest in prohibiting financial fraud or acts of bribery being perpetrated upon Medicare providers,\" Justice Kennedy wrote for the court. \"Fraudulent acts threaten the program's integrity.","sumSrc":"Oyez","by":{"0":"37, 49","1":"40","2":"4"}},{"t":"case","label":"Gonzaga Univ. v. Doe","cite":"536 U.S. 273","y":2002,"id":"2001/01-679","sc":1,"sum":"The Court held that such an action is foreclosed because the relevant provisions of FERPA create no personal rights to enforce.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Jones v. United States","cite":"529 U.S. 848","y":2000,"id":"1999/99-5739","sc":1,"op":1,"sum":"Delivered by Justice Ruth Bader Ginsburg, the Court held that an owner-occupied residence not used for any commercial purpose does not qualify as property \"used in\" commerce or commerce-affecting activity, such that arson of such a dwelling is not subject to federal prosecution under section 844(i).","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Kelly v. United States","cite":"140 S. Ct. 1565","y":2020,"id":"2019/18-1059","sc":1,"sum":"The Court held that Baroni and Kelly, who executed the New Jersey “Bridgegate” political retribution scheme against Fort Lee’s mayor, did not violate the federal-program fraud or wire fraud laws because they did not aim to obtain money or property from the federal Port Authority.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"op":5,"sum":"The Court held that a conviction under 26 U.S.C. § 7212(a) for corruptly endeavoring to obstruct or impede the due administration of the tax laws requires proof that the defendant acted with knowledge of a pending Internal Revenue Service action.","sumSrc":"Oyez","by":{"0":"40","2":"17"}},{"t":"case","label":"Marx v. Gen. Rev. Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"28","2":"10"}},{"t":"case","label":"McCormick v. United States","cite":"500 U.S. 257","y":1991,"id":"1990/89-1918","sc":1,"op":1,"ar":2,"sum":"Petitioner McCormick, a member of the West Virginia House of Delegates in 1984, was a leading advocate of a legislative program allowing foreign medical school graduates to practice under temporary permits while studying for the state licensing exams. Some doctors practiced for years under the program, as they repeatedly failed those exams. He sponsored a bill, sought by an organization of those doctors, extending …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48","1":"33","2":"21"}},{"t":"case","label":"McCutcheon v. FEC","cite":"572 U.S. 185","y":2014,"id":"2013/12-536","sc":1,"sum":"The Court ruled that the two-year aggregate campaign contribution limit of the Bipartisan Campaign Reform Act was unconstitutional.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"op":5,"ar":2,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"0":"38-40, 43, 45, 49","1":"21, 24, 25, 34","2":"6, 18, 22"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"sum":"Section 6010 does not create in favor of the mentally retarded any substantive rights to \"appropriate treatment\" in the \"least restrictive\" environment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46-47"}},{"t":"case","label":"People v. Johnston","cite":"43 N.W.2d 334","y":1950,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/43/334/","by":{"0":"24"}},{"t":"case","label":"People v. Seeley","cite":"69 P. 693","y":1902,"court":"Cal.","url":"https://www.courtlistener.com/c/P./69/693/","by":{"0":"24"}},{"t":"case","label":"Percoco v. United States","cite":"598 U.S. 319","y":2023,"id":"2022/21-1158","sc":1,"op":1,"sum":"Jury instructions on the legal standard for finding that a private citizen owes the government a duty of honest services based on the Second Circuit’s decision in United States v. Margiotta, 688 F. 2d 108 (1982), were erroneous.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25","2":"23"}},{"t":"case","label":"Perrin v. United States","cite":"444 U.S. 37","y":1979,"id":"1979/78-959","sc":1,"sum":"Bribery of private employees prohibited by state criminal statutes violates the Travel Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Peter v. Nantkwest, Inc.","cite":"140 S. Ct. 365","y":2019,"id":"2019/18-801","sc":1,"sum":"The Court held that the phrase “[a]ll the expenses of the proceedings” in 35 U.S.C. § 145 does not include attorneys’ fees incurred as a result of defending the agency in § 145 litigation.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Sabri v. United States","cite":"541 U.S. 600","y":2004,"id":"2003/03-44","sc":1,"op":3,"ar":3,"sum":"The Court held that Article I of the Constitution allows Congress to prohibit bribery of organizations that distribute federal funds. The Justices found that the Spending Clause authorizes Congress to spend money for the general welfare, and that the Necessary and Proper Clause authorizes it to take any reasonable steps to prevent such money from being misspent.","sumSrc":"Oyez","by":{"0":"47-48","1":"3, 26-28, 32, 35","2":"4, 19"}},{"t":"case","label":"Sackett v. EPA","cite":"598 U.S. 651","y":2023,"id":"2022/21-454","sc":1,"sum":"The Clean Water Act extends only to wetlands that have a continuous surface connection with “waters” of the United States—i.e., with a relatively permanent body of water connected to traditional interstate navigable waters, 33 U. S. C. §1362(7)—making it difficult to determine where the water ends and the wetland begins.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"27"}},{"t":"case","label":"Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"op":4,"sum":"The Court held that section 666(a)(1)(B) does not require the Government to prove the bribe in question had a demonstrated effect upon federal funds.","sumSrc":"Oyez","by":{"0":"47","1":"27, 28","2":"5"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"op":1,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"0":"40","1":"34"}},{"t":"case","label":"State v. Ellis","cite":"33 N.J.L. 102","y":1868,"court":"N.J. Sup. Ct.","url":"https://www.courtlistener.com/c/N.J.L./33/102/","by":{"0":"18"}},{"t":"case","label":"State v. Milbrath","cite":"527 So. 2d 864","y":1988,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/527/864/","by":{"0":"24"}},{"t":"case","label":"Sw. Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/450/","sc":1,"by":{"0":"26"}},{"t":"case","label":"United States v. Alfisi","cite":"308 F.3d 144","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/308/144/","by":{"0":"24"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"op":1,"ar":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43, 46"}},{"t":"case","label":"United States v. Brewster","cite":"506 F.2d 62","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/506/62/","by":{"0":"22"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"49"}},{"t":"case","label":"United States v. Evans","cite":"572 F.2d 455","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/572/455/","by":{"0":"31"}},{"t":"case","label":"United States v. Fernandez","cite":"722 F.3d 1","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/722/1/","op":2,"by":{"0":"18, 20-21, 33, 37, 50","1":"14, 40","2":"6"}},{"t":"case","label":"United States v. Gatling","cite":"96 F.3d 1511","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/96/1511/","by":{"0":"24"}},{"t":"case","label":"United States v. Hamilton","cite":"46 F.4th 389","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/46/389/","op":5,"by":{"0":"33, 50","1":"14","2":"19"}},{"t":"case","label":"United States v. Jennings","cite":"160 F.3d 1006","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/160/1006/","by":{"0":"18, 20"}},{"t":"case","label":"United States v. Johnson","cite":"621 F.2d 1073","y":1980,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/621/1073/","by":{"0":"24"}},{"t":"case","label":"United States v. Lindberg","cite":"39 F.4th 151","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/39/151/","sum":"Recognizing that Section 666 requires a nexus to specific business or transactions.","sumSrc":"brief:1","by":{"0":"38","1":"38"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"United States v. Strand","cite":"574 F.2d 993","y":1978,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/574/993/","by":{"0":"24"}},{"t":"case","label":"United States v. Sun-Diamond Growers of Cal.","cite":"526 U.S. 398","y":1999,"id":"1998/98-131","sc":1,"op":11,"ar":4,"sum":"Holding that to establish a violation of § 201(c), “the Govern- Page Proof Pending Publication ment must prove a link between a thing of value conferred upon a public offcial and a specifc `offcial act' for or because of which it was given” (emphasis added).","sumSrc":"opinion","by":{"0":"22, 28, 32, 38, 42, 48-49","1":"4, 6, 15, 17, 19, 21, 22, 24, 26, 28, 37, 38","2":"3, 11"}},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"sum":"An individual “exceeds authorized access” under the Computer Fraud and Abuse Act of 1986, 18 U. S. C. §1030(a)(2), when he accesses a computer with authorization but then obtains information located in particular areas of the computer—such as files, folders, or databases—that are off-limits to him.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18, 36"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"op":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"49"}},{"t":"usc","label":"10 U.S.C. § 924a","url":"https://www.law.cornell.edu/uscode/text/10/924a","by":{"0":"29"}},{"t":"usc","label":"13 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/13/211","by":{"0":"19"}},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","subs":["(b)","(b)(1)","(b)(2)","(c)","(c)(1)(A)","(g)(1982)","(g)"],"stext":{"head":"§201. Bribery of public officials and witnesses","paras":[[0,"(a) For the purpose of this section—"],[1,"(1) the term \"public official\" means Member of Congress, Delegate, or Resident Commissioner, either before or after such official has qualified, or an officer or employee or person acting for or on behalf of the United States, or any department, agency or branch of Government thereof, including the District of Columbia, in any official function, under or by authority of any such department, agency, or branch of Government, or a juror;"],[1,"(2) the term \"person who has been selected to be a public official\" means any person who has been nominated or appointed to be a public official, or has been officially informed that such person will be so nominated or appointed; and"],[1,"(3) the term \"official act\" means any decision or action on any question, matter, cause, suit, proceeding or controversy, which may at any time be pending, or which may by law be brought before any public official, in such official's official capacity, or in such official's place of trust or profit."],[0,"(b) Whoever—"],[1,"(1) directly or indirectly, corruptly gives, offers or promises anything of value to any public official or person who has been selected to be a public official, or offers or promises any public official or any person who has been selected to be a public official to give anything of value to any other person or entity, with intent—"],[2,"(A) to influence any official act; or"],[2,"(B) to influence such public official or person who has been selected to be a public official to commit or aid in committing, or collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) to induce such public official or such person who has been selected to be a public official to do or omit to do any act in violation of the lawful duty of such official or person;"],[1,"(2) being a public official or person selected to be a public official, directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity, in return for:"],[2,"(A) being influenced in the performance of any official act;"],[2,"(B) being influenced to commit or aid in committing, or to collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) being induced to do or omit to do any act in violation of the official duty of such official or person;"],[1,"(3) directly or indirectly, corruptly gives, offers, or promises anything of value to any person, or offers or promises such person to give anything of value to any other person or entity, with intent to influence the testimony under oath or affirmation of such first-mentioned person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or with intent to influence such person to absent himself therefrom;"],[1,"(4) directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity in return for being influenced in testimony under oath or affirmation as a witness upon any such trial, hearing, or other proceeding, or in return for absenting himself therefrom;"],[1,"shall be fined under this title or not more than three times the monetary equivalent of the thing of value, whichever is greater, or imprisoned for not more than fifteen years, or both, and may be disqualified from holding any office of honor, trust, or profit under the United States."],[0,"(c) Whoever—"],[1,"(1) otherwise than as provided by law for the proper discharge of official duty—"],[2,"(A) directly or indirectly gives, offers, or promises anything of value to any public official, former public official, or person selected to be a public official, for or because of any official act performed or to be performed by such public official, former public official, or person selected to be a public official; or"],[2,"(B) being a public official, former public official, or person selected to be a public official, otherwise than as provided by law for the proper discharge of official duty, directly or indirectly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of any official act performed or to be performed by such official or person;"],[1,"(2) directly or indirectly, gives, offers, or promises anything of value to any person, for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or for or because of such person's absence therefrom;"],[1,"(3) directly or indirectly, demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon any such trial, hearing, or other proceeding, or for or because of such person's absence therefrom;"],[1,"shall be fined under this title or imprisoned for not more than two years, or both."],[0,"(d) Paragraphs (3) and (4) of subsection (b) and paragraphs (2) and (3) of subsection (c) shall not be construed to prohibit the payment or receipt of witness fees provided by law, or the payment, by the party upon whose behalf a witness is called and receipt by a witness, of the reasonable cost of travel and subsistence incurred and the reasonable value of time lost in attendance at any such trial, hearing, or proceeding, or in the case of expert witnesses, a reasonable fee for time spent in the preparation of such opinion, and in appearing and testifying."],[0,"(e) The offenses and penalties prescribed in this section are separate from and in addition to those prescribed in sections 1503, 1504, and 1505 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/201?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":2,"head":"§201. Bribery of public officials and witnesses","tname":"Crimes and Criminal Procedure","by":{"0":"13-14, 29, 40","1":"6, 7, 14, 16, 17, 26-28, 34, 37, 42, 21, 24, 28, 21, 24, 21, 24, 6, 17, 20, 23, 34, 37, 38, 43, 37, 29, 42, 6, 42, 29, 42, 6","2":"6, 10, 16"}},{"t":"usc","label":"18 U.S.C. § 666","url":"https://www.law.cornell.edu/uscode/text/18/666","subs":["(a)(1)(A)","(a)","(a)(1)(B)","(a)(2)","(b)","(c)"],"stext":{"head":"§666. Theft or bribery concerning programs receiving Federal funds","paras":[[0,"(a) Whoever, if the circumstance described in subsection (b) of this section exists—"],[1,"(1) being an agent of an organization, or of a State, local, or Indian tribal government, or any agency thereof—"],[2,"(A) embezzles, steals, obtains by fraud, or otherwise without authority knowingly converts to the use of any person other than the rightful owner or intentionally misapplies, property that—"],[3,"(i) is valued at $5,000 or more, and"],[3,"(ii) is owned by, or is under the care, custody, or control of such organization, government, or agency; or"],[2,"(B) corruptly solicits or demands for the benefit of any person, or accepts or agrees to accept, anything of value from any person, intending to be influenced or rewarded in connection with any business, transaction, or series of transactions of such organization, government, or agency involving any thing of value of $5,000 or more; or"],[1,"(2) corruptly gives, offers, or agrees to give anything of value to any person, with intent to influence or reward an agent of an organization or of a State, local or Indian tribal government, or any agency thereof, in connection with any business, transaction, or series of transactions of such organization, government, or agency involving anything of value of $5,000 or more;"],[0,"shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(b) The circumstance referred to in subsection (a) of this section is that the organization, government, or agency receives, in any one year period, benefits in excess of $10,000 under a Federal program involving a grant, contract, subsidy, loan, guarantee, insurance, or other form of Federal assistance."],[0,"(c) This section does not apply to bona fide salary, wages, fees, or other compensation paid, or expenses paid or reimbursed, in the usual course of business."],[0,"(d) As used in this section—"],[1,"(1) the term \"agent\" means a person authorized to act on behalf of another person or a government and, in the case of an organization or government, includes a servant or employee, and a partner, director, officer, manager, and representative;"],[1,"(2) the term \"government agency\" means a subdivision of the executive, legislative, judicial, or other branch of government, including a department, independent establishment, commission, administration, authority, board, and bureau, and a corporation or other legal entity established, and subject to control, by a government or governments for the execution of a governmental or intergovernmental program;"],[1,"(3) the term \"local\" means of or pertaining to a political subdivision within a State;"],[1,"(4) the term \"State\" includes a State of the United States, the District of Columbia, and any commonwealth, territory, or possession of the United States; and"],[1,"(5) the term \"in any one-year period\" means a continuous period that commences no earlier than twelve months before the commission of the offense or that ends no later than twelve months after the commission of the offense. Such period may include time both before and after the commission of the offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/666?type=usc&year=mostrecent&link-type=html"},"op":130,"ar":12,"head":"§666. Theft or bribery concerning programs receiving Federal funds","tname":"Crimes and Criminal Procedure","by":{"0":"5, 21, 26, 48, 5, 36","1":"1, 3, 7, 11, 13-18, 21, 23, 25-33, 35-39, 42, 43, 2, 41, 2, 3, 8, 11, 12, 15, 17, 18, 20, 24, 36-38, 2, 3, 8, 18, 27, 37, 38, 16, 42, 2, 29, 2, 17, 26, 36"}},{"t":"usc","label":"19 U.S.C. § 60","url":"https://www.law.cornell.edu/uscode/text/19/60","by":{"0":"30-31"}},{"t":"usc","label":"22 U.S.C. § 4202","url":"https://www.law.cornell.edu/uscode/text/22/4202","stext":{"head":"§4202. Exaction of excessive fees for verification of invoices; penalty","paras":[[0,"The fee provided by law for the verification of invoices by consular officers shall, when paid, be held to be a full payment for furnishing blank forms of declaration to be signed by the shipper, and for making, signing, and sealing the certificate of the consular officer thereto; and any consular officer who, under pretense of charging for blank forms, advice, or clerical services in the preparation of such declaration or certificate, charges or receives any fee greater in amount than that provided by law for the verification of invoices, or who demands or receives for any official services, or who allows any clerk or subordinate to receive for any such service, any fee or reward other than the fee provided by law for such service, shall be punishable by imprisonment for not more than one year, or by a fine of not more than $2,000, and shall be removed from his office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/4202?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4202. Exaction of excessive fees for verification of invoices; penalty","tname":"Foreign Relations and Intercourse","by":{"0":"30-31","1":"20","2":"11"}},{"t":"usc","label":"26 U.S.C. § 7212","url":"https://www.law.cornell.edu/uscode/text/26/7212","subs":["(a)"],"stext":{"head":"§7212. Attempts to interfere with administration of internal revenue laws","paras":[[0,"(a) Corrupt or forcible interference"],[0,"Whoever corruptly or by force or threats of force (including any threatening letter or communication) endeavors to intimidate or impede any officer or employee of the United States acting in an official capacity under this title, or in any other way corruptly or by force or threats of force (including any threatening letter or communication) obstructs or impedes, or endeavors to obstruct or impede, the due administration of this title, shall, upon conviction thereof, be fined not more than $5,000, or imprisoned not more than 3 years, or both, except that if the offense is committed only by threats of force, the person convicted thereof shall be fined not more than $3,000, or imprisoned not more than 1 year, or both. The term \"threats of force\", as used in this subsection, means threats of bodily harm to the officer or employee of the United States or to a member of his family."],[0,"(b) Forcible rescue of seized property"],[0,"Any person who forcibly rescues or causes to be rescued any property after it shall have been seized under this title, or shall attempt or endeavor so to do, shall, excepting in cases otherwise provided for, for every such offense, be fined not more than $500, or not more than double the value of the property so rescued, whichever is the greater, or be imprisoned not more than 2 years."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7212?type=usc&year=mostrecent&link-type=html"},"head":"§7212. Attempts to interfere with administration of internal revenue laws","tname":"Internal Revenue Code","by":{"0":"7","1":"3, 11, 20, 26, 25"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"33 U.S.C. § 447","url":"https://www.law.cornell.edu/uscode/text/33/447","stext":{"head":"§447. Bribery of inspector; penalty","paras":[[0,"Every person who, directly or indirectly, gives any sum of money or other bribe, present, or reward, or makes any offer of the same to any inspector, deputy inspector, or other employee of the office of any supervisor of a harbor with intent to influence such inspector, deputy inspector, or other employee to permit or overlook any violation of the provisions of this subchapter, shall, on conviction thereof, be fined not less than $500 nor more than $1,000, and be imprisoned not less than six months nor more than one year."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/447?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§447. Bribery of inspector; penalty","tname":"Navigation and Navigable Waters","by":{"0":"19, 33","1":"23"}},{"t":"law","label":"Pub. L. No. 99-646","url":"https://www.govinfo.gov/link/statute/100/3592","by":{"0":"34"}},{"t":"reg","label":"2 C.F.R. § 200.318","url":"https://www.ecfr.gov/current/title-2/section-200.318","by":{"0":"47"}},{"t":"reg","label":"5 C.F.R. § 2635.201","url":"https://www.ecfr.gov/current/title-5/section-2635.201","by":{"0":"39"}},{"t":"reg","label":"20 C.F.R. § 10.703","url":"https://www.ecfr.gov/current/title-20/section-10.703","by":{"0":"30"}},{"t":"reg","label":"52 Fed. Reg. 46046","url":"https://www.govinfo.gov/link/fr/52/46046","by":{"0":"41","1":"31"}},{"t":"const","label":"Article III, Section 24","by":{"0":"45"}},{"t":"usc","label":"18 U.S.C. § 600","url":"https://www.law.cornell.edu/uscode/text/18/600","stext":{"head":"§600. Promise of employment or other benefit for political activity","paras":[[0,"Whoever, directly or indirectly, promises any employment, position, compensation, contract, appointment, or other benefit, provided for or made possible in whole or in part by any Act of Congress, or any special consideration in obtaining any such benefit, to any person as consideration, favor, or reward for any political activity or for the support of or opposition to any candidate or any political party in connection with any general or special election to any political office, or in connection with any primary election or political convention or caucus held to select candidates for any political office, shall be fined under this title or imprisoned not more than one year, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/600?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§600. Promise of employment or other benefit for political activity","tname":"Crimes and Criminal Procedure","by":{"0":"19","1":"22, 23"}},{"t":"case","label":"Burton v. United States","cite":"202 U.S. 344","y":1906,"id":"scdb/1905-122","sc":1,"sum":"Congress has power to make it an offense against the United States for a Senator or Representative, after his election and during his continuance in office, to agree to receive, or to receive, compensation for services before a Department of the Government, in relation to matters in which the United States is directly or indirectly interested, and § 1782, Rev. Stat., is not repugnant to the Constitution as …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"6"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"32, 33"}},{"t":"case","label":"Dixson v. United States","cite":"465 U.S. 482","y":1984,"id":"1983/82-5279","sc":1,"sum":"Petitioners are \"public officials\". within the meaning of §201(a) and thus are subject to prosecution under the bribery statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Evans v. United States","cite":"504 U.S. 255","y":1992,"id":"1991/90-6105","sc":1,"sum":"An affirmative act of inducement by a public official, such as a demand, is not an element of the offense of extortion \"under color of official right\" prohibited by the Hobbs Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Greer v. United States","cite":"593 U.S. 503","y":2021,"id":"2020/19-8709","sc":1,"op":1,"sum":"In felon-in-possession cases under 18 U. S. C. §922(g)(1), an error under Rehaif v. United States, 588 U. S. ___, is not a basis for plain-error relief unless the defendant first makes a sufficient argument or representation on appeal that he would have presented evidence at trial that he did not in fact know he was a felon.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"43"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"1":"31"}},{"t":"case","label":"Mason v. Muncaster","cite":"16 F. Cas. 1052","y":1828,"court":"C.C.D.D.C.","url":"https://www.courtlistener.com/c/F.%20Cas./16/1052/","by":{"1":"4"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Def.","cite":"583 U.S. 109","y":2018,"id":"2017/16-299","sc":1,"op":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Northcross v. Board of Educ.","cite":"412 U.S. 427","y":1973,"id":"1972/72-1164","sc":1,"sum":"Since the Court of Appeals' denial of costs and attorneys' fees under § 718 of the Emergency School Aid Act of 1972 to petitioners, who were successful in litigation -aimed at desegregating the public schools of Memph s, Tenn., was without'stated reasons, this Court cannot determine whether the prqper standard, Newman v. Piggie Park Enterp2es, Inc., 390 U. S. 400, was correctly applied. Certiorari granted;.vacated …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Ocasio v. United States","cite":"578 U.S. 282","y":2016,"id":"2015/14-361","sc":1,"sum":"The Court determined that a conspiracy to commit extortion can involve the purported victims of the extortion as members of the conspiracy.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Sorich v. United States","cite":"555 U.S. 1204","y":2009,"url":"https://supreme.justia.com/cases/federal/us/555/1204/","sc":1,"op":1,"sum":"Describing § 666(a) as providing a “clear rul[e]” prohibiting “bribes and gratuities to public offcials”.","sumSrc":"opinion","by":{"1":"17, 18, 35","2":"4"}},{"t":"case","label":"State v. Brown","cite":"267 S.W.2d 682","y":1954,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/267/682/","by":{"1":"6"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"op":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"28"}},{"t":"case","label":"United States v. Ganim","cite":"510 F.3d 134","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/510/134/","by":{"1":"21","2":"5"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"sum":"Title 8 U. S. C. §1324(a)(1)(A)(iv)—which criminalizes “encouraging or inducing” illegal immigration—forbids only the purposeful solicitation and facilitation of specific acts known to violate federal law and is not unconstitutionally overbroad.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34, 40"}},{"t":"case","label":"United States v. Hawkins","cite":"777 F.3d 880","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/880/","by":{"1":"11, 14","2":"23, 23"}},{"t":"case","label":"United States v. Johnson","cite":"874 F.3d 990","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/990/","by":{"1":"11","2":"23"}},{"t":"case","label":"United States ex rel. Schutte v. SuperValu Inc.","cite":"598 U.S. 739","y":2023,"id":"2022/21-1326","sc":1,"sum":"The False Claims Act’s scienter element—which asks whether a defendant “knowingly” submitted a “false” claim to the Government, 31 U. S. C. §3729(a)—refers to a defendant’s knowledge and subjective beliefs—not to what an objectively reasonable person may have known or believed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"35"}},{"t":"case","label":"United States v. Terry","cite":"707 F.3d 607","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/707/607/","by":{"1":"33"}},{"t":"const","label":"Article II, Section 1, Clause 7","text":"The President shall, at stated Times, receive for his Services, a Compensation, which shall neither be encreased nor diminished during the Period for which he shall have been elected, and he shall not receive within that Period any other Emolument from the United States, or any of them.","by":{"1":"4","2":"11"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"16, 33, 34"}},{"t":"law","label":"Pub. L. No. 87-849","url":"https://www.govinfo.gov/link/statute/76/1119","by":{"1":"6","2":"12"}},{"t":"law","label":"Pub. L. No. 99-370","url":"https://www.govinfo.gov/link/statute/100/779","by":{"1":"30, 31","2":"13"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/2143","by":{"1":"7, 28"}},{"t":"law","label":"Pub. L. No. 101-647","url":"https://www.govinfo.gov/link/statute/104/4789","by":{"1":"42"}},{"t":"law","label":"Pub. L. No. 96-646","url":"https://www.govinfo.gov/link/statute/100/3592","by":{"1":"7, 8, 29"}},{"t":"law","label":"Pub. L. No. 101-73","url":"https://www.govinfo.gov/link/statute/103/499","by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/18/206","subs":["(1958)"],"by":{"1":"42"}},{"t":"usc","label":"18 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/18/207","subs":["(1958)"],"by":{"1":"42"}},{"t":"usc","label":"18 U.S.C. § 215","url":"https://www.law.cornell.edu/uscode/text/18/215","subs":["(a)","(a)(2)","(d)"],"stext":{"head":"§215. Receipt of commissions or gifts for procuring loans","paras":[[0,"(a) Whoever—"],[1,"(1) corruptly gives, offers, or promises anything of value to any person, with intent to influence or reward an officer, director, employee, agent, or attorney of a financial institution in connection with any business or transaction of such institution; or"],[1,"(2) as an officer, director, employee, agent, or attorney of a financial institution, corruptly solicits or demands for the benefit of any person, or corruptly accepts or agrees to accept, anything of value from any person, intending to be influenced or rewarded in connection with any business or transaction of such institution;"],[0,"shall be fined not more than $1,000,000 or three times the value of the thing given, offered, promised, solicited, demanded, accepted, or agreed to be accepted, whichever is greater, or imprisoned not more than 30 years, or both, but if the value of the thing given, offered, promised, solicited, demanded, accepted, or agreed to be accepted does not exceed $1,000, shall be fined under this title or imprisoned not more than one year, or both."],[0,"[(b) Transferred]"],[0,"(c) This section shall not apply to bona fide salary, wages, fees, or other compensation paid, or expenses paid or reimbursed, in the usual course of business."],[0,"(d) Federal agencies with responsibility for regulating a financial institution shall jointly establish such guidelines as are appropriate to assist an officer, director, employee, agent, or attorney of a financial institution to comply with this section. Such agencies shall make such guidelines available to the public."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/215?type=usc&year=mostrecent&link-type=html"},"op":14,"ar":2,"head":"§215. Receipt of commissions or gifts for procuring loans","tname":"Crimes and Criminal Procedure","by":{"1":"16, 27, 29-31, 42, 31, 29, 31, 42, 31"}},{"t":"usc","label":"18 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/18/1346","by":{"1":"34"}},{"t":"usc","label":"18 U.S.C. § 1422","url":"https://www.law.cornell.edu/uscode/text/18/1422","stext":{"head":"§1422. Fees in naturalization proceedings","paras":[[0,"Whoever knowingly demands, charges, solicits, collects, or receives, or agrees to charge, solicit, collect, or receive any other or additional fees or moneys in proceedings relating to naturalization or citizenship or the registry of aliens beyond the fees and moneys authorized by law, shall be fined under this title or imprisoned not more than five years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1422?type=usc&year=mostrecent&link-type=html"},"head":"§1422. Fees in naturalization proceedings","tname":"Crimes and Criminal Procedure","by":{"1":"42","2":"12"}},{"t":"usc","label":"18 U.S.C. § 1503","url":"https://www.law.cornell.edu/uscode/text/18/1503","subs":["(a)"],"by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 1505","url":"https://www.law.cornell.edu/uscode/text/18/1505","by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 1912","url":"https://www.law.cornell.edu/uscode/text/18/1912","stext":{"head":"§1912. Unauthorized fees for inspection of vessels","paras":[[0,"Whoever, being an officer, employee, or agent of the United States or any agency thereof, engaged in inspection of vessels, upon any pretense, receives any fee or reward for his services, except what is allowed to him by law, shall be fined under this title or imprisoned not more than six months, or both; and shall forfeit his office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1912?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1912. Unauthorized fees for inspection of vessels","tname":"Crimes and Criminal Procedure","by":{"1":"20"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)(6)"],"by":{"1":"43"}},{"t":"usc","label":"26 U.S.C. § 7214","url":"https://www.law.cornell.edu/uscode/text/26/7214","subs":["(a)"],"stext":{"head":"§7214. Offenses by officers and employees of the United States","paras":[[0,"(a) Unlawful acts of revenue officers or agents"],[0,"Any officer or employee of the United States acting in connection with any revenue law of the United States—"],[1,"(1) who is guilty of any extortion or willful oppression under color of law; or"],[1,"(2) who knowingly demands other or greater sums than are authorized by law, or receives any fee, compensation, or reward, except as by law prescribed, for the performance of any duty; or"],[1,"(3) who with intent to defeat the application of any provision of this title fails to perform any of the duties of his office or employment; or"],[1,"(4) who conspires or colludes with any other person to defraud the United States; or"],[1,"(5) who knowingly makes opportunity for any person to defraud the United States; or"],[1,"(6) who does or omits to do any act with intent to enable any other person to defraud the United States; or"],[1,"(7) who makes or signs any fraudulent entry in any book, or makes or signs any fraudulent certificate, return, or statement; or"],[1,"(8) who, having knowledge or information of the violation of any revenue law by any person, or of fraud committed by any person against the United States under any revenue law, fails to report, in writing, such knowledge or information to the Secretary; or"],[1,"(9) who demands, or accepts, or attempts to collect, directly or indirectly as payment or gift, or otherwise, any sum of money or other thing of value for the compromise, adjustment, or settlement of any charge or complaint for any violation or alleged violation of law, except as expressly authorized by law so to do;"],[0,"shall be dismissed from office or discharged from employment and, upon conviction thereof, shall be fined not more than $10,000, or imprisoned not more than 5 years, or both. The court may in its discretion award out of the fine so imposed an amount, not in excess of one-half thereof, for the use of the informer, if any, who shall be ascertained by the judgment of the court. The court also shall render judgment against the said officer or employee for the amount of damages sustained in favor of the party injured, to be collected by execution."],[0,"(b) Interest of internal revenue officer or employee in tobacco or liquor production"],[0,"Any internal revenue officer or employee interested, directly or indirectly, in the manufacture of tobacco, snuff, or cigarettes, or in the production, rectification, or redistillation of distilled spirits, shall be dismissed from office; and each such officer or employee so interested in any such manufacture or production, rectification, or redistillation or production of fermented liquors shall be fined not more than $5,000."],[0,"(c) Cross reference"],[2,"For penalty on collecting or disbursing officers trading in public funds or debts or property, see 18 U.S.C. 1901."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7214?type=usc&year=mostrecent&link-type=html"},"head":"§7214. Offenses by officers and employees of the United States","tname":"Internal Revenue Code","by":{"1":"42","2":"11-12"}},{"t":"reg","label":"52 Fed. Reg. 43,939","url":"https://www.govinfo.gov/link/fr/52/43939","by":{"1":"31"}},{"t":"case","label":"Blockburger v. United States","cite":"284 U.S. 299","y":1932,"id":"scdb/1931-120","sc":1,"sum":"1. Two salesof morphine not in or from the original stamped package, the second having been initiated after the first was complete, held separate and distinct offenses under § 1 of the Narcotics Act, although buyer and seller were the same in both cases and but little time elapsed between the end of the one transaction and the beginning of the other.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"Rewis v. United States","cite":"401 U.S. 808","y":1971,"id":"1970/5342","sc":1,"sum":"Conducting a gambling operation frequented by out-of-state bettors does not, without more, constitute a.violation of the Travel Act. Pp. 811-814. 418 F. 2d 1218, reversed. MARSHALL, J.,.delivered the opinion of the *Court, in which all members joined except WHITE, J., who took no part in the decision of the case.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"United States v. Bonito","cite":"57 F.3d 167","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/57/167/","op":1,"by":{"2":"5"}},{"t":"case","label":"United States v. Boyland","cite":"862 F.3d 279","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/862/279/","by":{"2":"16"}},{"t":"case","label":"United States v. Ford","cite":"435 F.3d 204","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/435/204/","by":{"2":"6, 22"}},{"t":"case","label":"United States v. Kaufman","cite":"2023 WL 1871669","y":2023,"court":"2d Cir. Feb. 10","by":{"2":"13"}},{"t":"case","label":"United States v. Lonich","cite":"23 F.4th 881","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/23/881/","by":{"2":"13"}},{"t":"case","label":"United States v. O’Brien","cite":"560 U.S. 218","y":2010,"id":"2009/08-1569","sc":1,"sum":"The Court held that the fact that a firearm was a machine gun is an element to be proved to the jury beyond a reasonable doubt, not a sentencing factor to be proved to the judge at sentencing.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"United States v. Roberson","cite":"998 F.3d 1237","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/998/1237/","by":{"2":"16"}},{"t":"case","label":"United States v. Robinson","cite":"663 F.3d 265","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/663/265/","by":{"2":"17"}},{"t":"case","label":"United States v. Rodrigues","cite":"159 F.3d 439","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/159/439/","by":{"2":"13"}},{"t":"const","label":"Article I, Section 9, Clause 8","clauses":[["emoluments","Emoluments Clauses"]],"text":"No Title of Nobility shall be granted by the United States: And no Person holding any Office of Profit or Trust under them, shall, without the Consent of the Congress, accept of any present, Emolument, Office, or Title, of any kind whatever, from any King, Prince, or foreign State.","by":{"2":"11"}},{"t":"reg","label":"5 C.F.R. § 2635.204","url":"https://www.ecfr.gov/current/title-5/section-2635.204","by":{"2":"9"}},{"t":"case","label":"Other Authorities—continued: U.S. Brief, United States v. Grace","cite":"568 F. App’x 344","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/568/344/","op":4,"by":{"2":"22"}},{"t":"case","label":"U.S. Brief, United States v. McGee","cite":"612 F.3d 627","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/612/627/","by":{"2":"23"}},{"t":"case","label":"U.S. Brief, United States v. Velazquez-Corchado","cite":"2014 WL 2994358","by":{"2":"23"}}]};